// nau-filter.js — NAU 필터(A 유화 v3 · B 크레용 v2 · C 크레용 페이퍼) 웹 모듈. ES 모듈, 의존성 없음(WebGL2)
// 갤러리 bba7e36 2026-11-09에서 tools/build_module.py가 만들었다. 손으로 고치지 말고 갤러리를 고친 뒤 다시 만든다.
// 쓰는 법은 nau-filter-guide.md
/* eslint-disable */

// ---------- 셰이더(갤러리 그대로) ----------
const VS = `#version 300 es
const vec2 P[3] = vec2[3](vec2(-1.,-1.), vec2(3.,-1.), vec2(-1.,3.));
out vec2 vUV;
void main(){ vec2 p = P[gl_VertexID]; vUV = p*0.5+0.5; gl_Position = vec4(p,0.,1.); }`;
const COMMON = `#version 300 es
precision highp float;
in vec2 vUV; out vec4 o;
uniform vec2 uRes; uniform vec2 uTexel; uniform float uSeed; uniform float uBoil;
float hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx)*.1031); p3 += dot(p3, p3.yzx+33.33); return fract((p3.x+p3.y)*p3.z); }
vec2 hash22(vec2 p){ vec3 p3 = fract(vec3(p.xyx)*vec3(.1031,.1030,.0973)); p3 += dot(p3,p3.yzx+33.33); return fract((p3.xx+p3.yz)*p3.zy); }
float vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.-2.*f);
  return mix(mix(hash12(i),hash12(i+vec2(1,0)),u.x), mix(hash12(i+vec2(0,1)),hash12(i+vec2(1,1)),u.x), u.y); }
float fbm(vec2 p){ float a=.5, s=0.; for(int i=0;i<5;i++){ s+=a*vnoise(p); p=p*2.03+17.1; a*=.5; } return s; }
float lum(vec3 c){ return dot(c, vec3(.299,.587,.114)); }
// 떨림 비율만큼 '이 그림만의' 잡음을 섞는다 (평균 0)
vec2 boilOff(float salt){ return hash22(vec2(uSeed*1.37+salt, salt*7.1))*997.; }
float bn(vec2 p, float salt){
  float a = vnoise(p + vec2(salt*31.7, salt*17.3)) - .5;
  float b = vnoise(p + boilOff(salt)) - .5;
  return sqrt(1.-uBoil)*a + sqrt(uBoil)*b;
}
float bfbm(vec2 p, float salt){
  float a = fbm(p + vec2(salt*13.1, salt*5.7));
  float b = fbm(p + boilOff(salt));
  return mix(a, b, uBoil);
}
`;
const FS_GRADE = COMMON + `
uniform sampler2D uSrc, uFigM; uniform float uAmt, uKeepW, uWLift;
void main(){
  vec3 c = texture(uSrc, vUV).rgb;
  vec3 g = c*vec3(1.035,1.0,0.94);
  float l = lum(g); g = mix(vec3(l), g, 1.0);
  float k = 0.08; g = g*(1.+k)/(1.+k*g);
  g = mix(g, vec3(.15,.10,.07), .03);
  vec3 r = mix(c, g, uAmt);
  // 흰색 지키기(세부 조정, 기본 0 = 그대로): 따뜻한 색 보정이 흰 털·종이를 크림색으로 만들지 않게 밝은 무채색만 원본으로
  // (푸빌라 가이드: 따뜻한 빛 아래서도 순백). 곰 이마 R−B가 색 보정 1에서 +0.08 안팎이다(10/21 측정)
  if (uKeepW > 0.) {
    float mx = max(c.r, max(c.g, c.b)), sat = (mx - min(c.r, min(c.g, c.b)))/(mx + 1e-3);
    r = mix(r, c, uKeepW*smoothstep(.62, .85, lum(c))*(1. - smoothstep(.08, .22, sat)));
  }
  // 푸빌라(마스크 1번) 흰 털 음영 덜기(CR.wlift, 10/22 '푸빌라 얼굴이 하얀 부분인데 저렇게 지는 게 문제 — 조금만 더 하얗게', 3D 소스 유화).
  // 밝은 무채색만 흰색 쪽으로 끌어올리고(음영 대비 × (1 − wlift)) 회청 기운을 뺀다. 눈·코(어두움)·목도리(채도 높음)는 그대로
  if (uWLift > 0.) {
    float v = texture(uFigM, vUV).r*255./40., isP = 1. - smoothstep(.35, .7, abs(v - 1.));
    float mx = max(r.r, max(r.g, r.b)), sat = (mx - min(r.r, min(r.g, r.b)))/(mx + 1e-3), L = lum(r);
    float wm = isP*smoothstep(.2, .55, L)*(1. - smoothstep(.14, .4, sat));   // 문턱을 넓게(밤빛 속 털은 밝기 .4~.6이라 좁은 문턱이면 켜졌다 꺼졌다 튄다)
    vec3 W = vec3(.975, .972, .962);
    vec3 q = r + (W - r)*uWLift; q = mix(q, vec3(lum(q))*vec3(1.004, 1., .99), .6*uWLift);
    r = mix(r, q, wm);
  }
  o = vec4(r, 1.);
}`;
const FS_SST = COMMON + `
uniform sampler2D uTex;
float L(vec2 d){ return lum(texture(uTex, vUV + d*uTexel).rgb); }
void main(){
  float tl=L(vec2(-1,1)), t=L(vec2(0,1)), tr=L(vec2(1,1));
  float l=L(vec2(-1,0)), r=L(vec2(1,0));
  float bl=L(vec2(-1,-1)), b=L(vec2(0,-1)), br=L(vec2(1,-1));
  float gx = (tr + 2.*r + br - tl - 2.*l - bl)*.25;
  float gy = (tl + 2.*t + tr - bl - 2.*b - br)*.25;
  o = vec4(gx*gx, gy*gy, gx*gy, 1.);
}`;
const FS_BLUR = COMMON + `
uniform sampler2D uTex; uniform vec2 uDir; uniform float uSigma;
void main(){
  vec4 s = vec4(0.); float ws = 0.; float R = ceil(2.*uSigma);
  for (int i=-12;i<=12;i++){ float fi=float(i); if (abs(fi)>R) continue;
    float w = exp(-fi*fi/(2.*uSigma*uSigma)); s += w*texture(uTex, vUV + fi*uDir); ws += w; }
  o = s/ws;
}`;
const FS_TFM = COMMON + `
uniform sampler2D uTex; uniform float uStrE;
uniform sampler2D uGr; uniform float uSlopeK;   // 그늘 띠 붓 방향(OIL.slope, 유화만): 크게 흐린 원본(밉 5)의 밝기 등고선
uniform sampler2D uPrev; uniform float uFlowK;   // 붓 방향 시간 평활(OIL.flowT, 유화만): 앞 그림의 방향을 이어받는 비율
void main(){
  vec3 g = texture(uTex, vUV).xyz; float E=g.x, G=g.y, F=g.z;
  float disc = sqrt((E-G)*(E-G) + 4.*F*F);
  float l1 = .5*(E+G+disc), l2 = .5*(E+G-disc);
  vec2 t = vec2(l1 - E, -F);
  t = length(t) > 1e-9 ? normalize(t) : vec2(0.,1.);
  float A = (l1+l2) > 1e-9 ? (l1-l2)/(l1+l2) : 0.;
  float str = (E+G)/(E+G+uStrE);                       // 결이 약한 곳의 문턱(CR.tfmE, 기본 4e-5). 3D 소스의 부드러운 음영은 붓 방향이 흔들려 키운다(10/22 유화 얼굴 6.7 → 2.9%)
  float w = clamp(A*str*1.3, 0., 1.);
  vec2 d = vec2(cos(1.0472), sin(1.0472));              // 평평한 곳의 기본 붓 방향 60도
  vec2 t2 = vec2(t.x*t.x - t.y*t.y, 2.*t.x*t.y), d2 = vec2(d.x*d.x - d.y*d.y, 2.*d.x*d.y);
  // 그늘 띠 붓 방향(11/05 재연 님 결함 후보 2 — 탁자 그림자 띠에서 짙은 굵은 획이 사선으로 아래로 늘어진 빗금, OIL.slope): 3D 소스는 결 문턱(tfmE 1e-3)이 높아
  // 부드러운 그림자 띠도 '결 없음'이라 기본 60도로 칠하고, 사선 획이 가로 띠를 가로질러 짙은 색을 끌고 내려간다. 결이 약한 곳의 기본 방향을
  // 크게 흐린 원본(밉 5)의 밝기 등고선 쪽으로 — 그러데이션이 .08~.16 넘게 뚜렷한 곳(그림자 띠 가운데)만. 얼굴 음영(대개 .06 안팎)은 그대로 둬
  // 10/22에 막은 얼굴 붓 방향 흔들림이 돌아오지 않게(정지 얼굴 반짝임 +15%, 낮은 문턱 .03~.08은 +44%)
  if (uSlopeK > 0.) {
    vec2 tx = 32./vec2(textureSize(uGr, 0));
    float gx = lum(textureLod(uGr, vUV + vec2(tx.x, 0.), 5.).rgb) - lum(textureLod(uGr, vUV - vec2(tx.x, 0.), 5.).rgb);
    float gy = lum(textureLod(uGr, vUV + vec2(0., tx.y), 5.).rgb) - lum(textureLod(uGr, vUV - vec2(0., tx.y), 5.).rgb);
    float mg = length(vec2(gx, gy));
    if (mg > 1e-5) { vec2 tc = vec2(-gy, gx)/mg; d2 = mix(d2, vec2(tc.x*tc.x - tc.y*tc.y, 2.*tc.x*tc.y), uSlopeK*smoothstep(.08, .16, mg)); }
  }
  vec2 m2 = mix(d2, t2, w);
  // 붓 방향 시간 평활(11/09 측정 — 원본 대비 초과 반짝임의 20~46%가 그림마다 다시 구한 붓 방향): 앞 그림의 방향(두 배 각)을 uFlowK만큼 섞는다.
  // 결 · 획 모양은 그대로이고 방향만 그림 사이에서 천천히 바뀐다. 장면이 바뀌거나 처음 그림이면 섞지 않는다(uFlowK = 0)
  float aw = A*str;
  if (uFlowK > 0.) { vec4 p = texture(uPrev, vUV); vec2 p2 = vec2(p.x*p.x - p.y*p.y, 2.*p.x*p.y); m2 = mix(m2, p2*max(length(m2), 1e-3), uFlowK); aw = mix(aw, p.w, uFlowK); }
  float ang = .5*atan(m2.y, m2.x);
  o = vec4(cos(ang), sin(ang), ang, aw);
}`;
const FS_AKF = COMMON + `
uniform sampler2D uTex; uniform sampler2D uTFM; uniform vec2 uSrcTexel;
uniform float uRadius, uLod, uQ, uHard, uSharp;
#define MAXK 16
void main(){
  vec4 t = texture(uTFM, vUV);
  float A = t.w, phi = t.z;
  float a = uRadius*clamp((1.+A), .1, 2.), b = uRadius*clamp(1./(1.+A), .1, 2.);
  float cp = cos(phi), sp = sin(phi);
  mat2 SR = mat2(.5/a, 0., 0., .5/b) * mat2(cp, -sp, sp, cp);
  int mx = int(sqrt(a*a*cp*cp + b*b*sp*sp)), my = int(sqrt(a*a*sp*sp + b*b*cp*cp));
  float zeta = 2./uRadius, zc = .58, sz = sin(zc), eta = (zeta + cos(zc))/(sz*sz);
  vec4 m[8]; vec3 s[8];
  for (int k=0;k<8;k++){ m[k]=vec4(0.); s[k]=vec3(0.); }
  for (int j=-MAXK;j<=MAXK;j++){ if (j<-my || j>my) continue;
    for (int i=-MAXK;i<=MAXK;i++){ if (i<-mx || i>mx) continue;
      vec2 v = SR*vec2(float(i), float(j));
      if (dot(v,v) > .25) continue;
      vec3 c = textureLod(uTex, vUV + vec2(float(i),float(j))*uSrcTexel/uQ, uLod).rgb;
      float w[8]; float sum = 0., z, vxx, vyy;
      vxx = zeta - eta*v.x*v.x; vyy = zeta - eta*v.y*v.y;
      z = max(0., v.y + vxx); w[0]=z*z; sum+=w[0];
      z = max(0.,-v.x + vyy); w[2]=z*z; sum+=w[2];
      z = max(0.,-v.y + vxx); w[4]=z*z; sum+=w[4];
      z = max(0., v.x + vyy); w[6]=z*z; sum+=w[6];
      vec2 r = .70710678*vec2(v.x - v.y, v.x + v.y);
      vxx = zeta - eta*r.x*r.x; vyy = zeta - eta*r.y*r.y;
      z = max(0., r.y + vxx); w[1]=z*z; sum+=w[1];
      z = max(0.,-r.x + vyy); w[3]=z*z; sum+=w[3];
      z = max(0.,-r.y + vxx); w[5]=z*z; sum+=w[5];
      z = max(0., r.x + vyy); w[7]=z*z; sum+=w[7];
      float g = exp(-3.125*dot(v,v)) / (sum + 1e-8);
      for (int k=0;k<8;k++){ float wk = w[k]*g; m[k] += vec4(c*wk, wk); s[k] += c*c*wk; }
    }
  }
  vec4 acc = vec4(0.);
  for (int k=0;k<8;k++){
    if (m[k].w < 1e-4) continue;                       // 표본이 없는 구역은 빼야 검은 테가 생기지 않는다
    vec3 mu = m[k].rgb/(m[k].w + 1e-8);
    vec3 va = abs(s[k]/(m[k].w + 1e-8) - mu*mu);
    float w = 1./(1. + pow(uHard*1000.*(va.r+va.g+va.b), .5*uSharp));
    acc += vec4(mu*w, w);
  }
  o = vec4(acc.w > 1e-6 ? acc.rgb/acc.w : textureLod(uTex, vUV, uLod).rgb, 1.);
}`;
const SBR_HEAD = `#version 300 es
precision highp float; precision highp int;
float hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx)*.1031); p3 += dot(p3, p3.yzx+33.33); return fract((p3.x+p3.y)*p3.z); }
float vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.-2.*f);
  return mix(mix(hash12(i),hash12(i+vec2(1,0)),u.x), mix(hash12(i+vec2(0,1)),hash12(i+vec2(1,1)),u.x), u.y); }
float fbm(vec2 p){ float a=.5, s=0.; for(int i=0;i<5;i++){ s+=a*vnoise(p); p=p*2.03+17.1; a*=.5; } return s; }
float lum(vec3 c){ return dot(c, vec3(.299,.587,.114)); }
// 획 하나(10/22, CPU → GPU): 획 목록에는 칸 번호만 있다(+(번호 + 1) = 고정 칸, −(번호 + 1) = 다시 놓는 칸). 자리(칸 안에서 흔듦) · 난수 둘을 여기서
// CPU ihash와 같은 정수 해시로 만든다 — 고정 칸은 처음 씨앗(uSBase), 다시 놓는 칸은 그림마다(uSSeed) 새로. 그리는 순서는 목록 순서 그대로다
// (예전에는 다시 놓는 칸의 순서도 그림마다 새로 섞었다 — 순서 열쇠도 고른 난수라 결의 통계는 같다)
uniform int uSBase, uSSeed, uSGw; uniform vec2 uSCell;
uint ihashU(uint a, uint b, uint c){ uint h = a*374761393u + b*668265263u + c*2147483647u; h = (h ^ (h >> 13u))*1274126177u; return h ^ (h >> 16u); }
float ihashF(uint a, uint b, uint c){ return float(ihashU(a, b, c))/4294967296.; }
vec4 strokeIn(float v){                         // 중심 x,y (0~1), 난수 2개
  uint i = uint(abs(v) - .5), sd = uint(uSBase) + (v < 0. ? uint(uSSeed + 1)*7919u : 0u), gw = uint(uSGw);
  return vec4((float(i % gw) + ihashF(i, sd, 2u))*uSCell.x, (float(i / gw) + ihashF(i, sd, 3u))*uSCell.y, ihashF(i, sd, 4u), ihashF(i, sd, 5u));
}
`;
const FIG_GLSL = `
uniform sampler2D uFig; uniform float uNK; uniform vec3 uNL;
vec4 figAt(vec2 uv){                                    // 캐릭터 지도: xyz = 부풀린 노말, w = 캐릭터 안(0~1, 꺼 두면 0)
  vec4 f = textureLod(uFig, uv, 0.); vec2 n = f.rg*2. - 1.;
  return vec4(n, sqrt(max(0., 1. - dot(n, n))), clamp(f.b*255./40., 0., 1.)*uNK);
}
float figShade(vec4 F){ vec3 L = normalize(uNL); return dot(F.xyz, L) - L.z; }   // 정면보다 빛을 더 받으면 +, 덜 받으면 −
`;
const VS_STROKE = SBR_HEAD + FIG_GLSL + `
layout(location=0) in float aI; vec4 aS;        // aI = 획 목록의 칸 번호(±) → aS = 중심 x,y (0~1), 난수 2개(strokeIn)
uniform sampler2D uGrade, uTFM, uCanvas;
uniform vec2 uRes;
uniform float uLen, uWid, uLod, uDetMin, uAng, uHiCut, uJit, uErrT, uCell;
uniform sampler2D uBlob; uniform float uEyeK;   // 작은 검정 덩이(눈·코) · 흰 점(눈송이·전구) 지도 FS_BLOB, 눈·코 테 정리 OIL.eye(유화만)
float blb(vec2 q){ vec2 b = texture(uBlob, q).rg; return max(b.r, b.g); }
uniform int uMedium;                            // 1 유화, 2 수채, 3 빗금, 4 윤곽
uniform float uNDir, uNBand, uNOTone, uNWhite, uNOBgDet, uNOEdge, uNOStep, uNOBand, uNOPatch, uNOSoft, uNODark, uNOSil, uNOSilW;
vec2 figDir(vec2 uv, vec2 d){                   // 캐릭터 안: 부풀린 높이의 등고선 쪽으로(획이 형태를 감싸 돈다)
  if (uNK <= 0. || uMedium != 1) return d;
  vec4 F = figAt(uv); float s = length(F.xy); if (s < 1e-4) return d;
  vec2 tc = vec2(-F.y, F.x)/s, c2 = vec2(tc.x*tc.x - tc.y*tc.y, 2.*tc.x*tc.y), d2 = vec2(d.x*d.x - d.y*d.y, 2.*d.x*d.y);
  float e = texture(uTFM, uv).w;                // 원래 흐름이 뚜렷한 곳(색 경계·눈·코·입)은 원래 방향 — 유화 획은 색 경계에서 멈추지 않아 등고선이 경계를 가로지르면 가시가 된다
  vec2 m = mix(d2, c2, uNDir*F.w*smoothstep(uNBand, uNBand + .33, s)*(1. - smoothstep(uNOEdge, uNOEdge + .3, e))); float a = .5*atan(m.y, m.x);
  vec2 r = vec2(cos(a), sin(a)); return dot(r, d) < 0. ? -r : r;
}
out vec2 vSt; out vec3 vCol; out float vR;
// 경계 옆 번짐 띠(11/05 재연 님 고름 — 흰 곰 둘레 분홍 · 짙은 붉은 테, 탁자 윗면 위 주황 무늬, 귀 둘레 테, OIL.spill): 굵은 · 중간 붓(밉 3.8 · 2.6)이
// 경계 위에서 섞인 색을 집어 폭 · 길이만큼 바탕 쪽으로 펴 바르고(탁자 위 무늬는 중간 붓이 30~80px 끌고 올라감), 뒤 층이 덮고 남은 조각이 경계와 나란한 띠가 된다.
// 색 차가 .03~.09라 합성 단계에서는 붓 색 흔들림(±.03)과 가를 수 없어 획 단계에서: 다음 자리가 아주 평평한 바탕(둘레 10px 네 방향이 .02 안 —
// 그러데이션 · 무늬는 평평하지 않음)이고 그 색이 획 색과 .04 넘게 다르면 거기서 멈춘다. 평평함을 .05로 느슨하게 하면 달무리 같은 그러데이션에서 획이 끊겨 밑칠이 구멍처럼 비쳤다
uniform float uSpillK;
bool spillTo(vec2 q, vec3 col){
  vec3 g = textureLod(uGrade, q, 1.).rgb; if (distance(g, col) <= .04/uSpillK) return false;   // 값 1 = .04, 작을수록 문턱이 높아(0.5 = .08) 덜 멈춘다
  vec2 tq = 10./vec2(textureSize(uGrade, 0));
  return max(max(distance(textureLod(uGrade, q + vec2(tq.x, 0.), 1.).rgb, g), distance(textureLod(uGrade, q - vec2(tq.x, 0.), 1.).rgb, g)),
             max(distance(textureLod(uGrade, q + vec2(0., tq.y), 1.).rgb, g), distance(textureLod(uGrade, q - vec2(0., tq.y), 1.).rgb, g))) < .02;
}
const int NSEG = 6;
