const FS_CCOMPOSE = SBR_HEAD + CRAYON_FLAT + FIG_GLSL + `
in vec2 vUV; out vec4 o;
uniform sampler2D uPaint, uSrc, uFlat, uGradeT;
uniform vec2 uRes, uTexel; uniform float uStr, uSplit, uG, uEdgeFix, uEdgeGrain, uEdgeR, uEdgeSmudge, uSpeck, uNInner, uNTearBg, uNInMode;
uniform float uTear, uTearRag, uTearFine, uTearFiber, uTearShadow, uTearLen; uniform vec2 uTearLight;
vec2 ragT(vec2 x){                                                  // 찢은 가장자리(콜라주 v2와 같은 모양): 굵은 굴곡 7px + 잔 섬유 2.2px. 화면에 고정
