float proj(vec3 x, vec3 b, vec3 a){ vec3 d = a - b; return clamp(dot(x - b, d)/max(dot(d, d), 1e-4), 0., 1.); }
vec3 FL(vec2 uv, float lod){ return textureLod(uFlat, uv, lod).rgb; }
vec3 PT(vec2 uv){ return textureLod(uPaint, uv, 0.).rgb; }
float cd(vec3 a, vec3 b){ vec3 d = a - b; return dot(d, d) + 2.*(lum(a) - lum(b))*(lum(a) - lum(b)); }
void main(){
