  }
  float eW = 0.;                                                      // 굵은 경계(양쪽 ±경계로 볼 폭이 다른 색 면)인가 — 찢은 종이의 흰 단면·그림자는 여기만(판자 선 같은 가는 선엔 없다)
  if (uEdgeFix + uEdgeGrain + uEdgeSmudge + tearL > 0.) {
