  c *= 1. + .03*uStr*(1. - whiteW(c))*(vnoise(gl_FragCoord.xy/5.5) + vnoise(gl_FragCoord.xy/13.) - 1.);   // 넓은 면엔 아주 옅은 얼룩만(1~2px 잔결을 깔면 레퍼런스보다 2배 거칠다). 흰 면은 깨끗하게
  c = mix(vec3(lum(c)), c, 1.12);                                 // 크레용 색은 맑고 진하다
