    float tv = .55*hash12(floor(gl_FragCoord.xy)) + .45*vnoise(gl_FragCoord.xy/1.7);
    float vl = smoothstep(.34, .16, tv);
    c = mix(c, c + (vec3(.97, .95, .9) - c)*.16, vl*uSpeck*(1. - whiteW(c)));   // 같은 색이 조금 밝아지는 정도(세게 하면 흰 소금처럼 튄다)
  }
