export async function loadMaskSequence(pattern, n = 1, { fps = 24, start = 0 } = {}) {
  const urls = pattern.includes("%03d") ? Array.from({ length: n }, (_, i) => pattern.replace("%03d", String(i + 1).padStart(3, "0"))) : [pattern];
  const frames = await Promise.all(urls.map(u => fetch(u).then(r => {
    if (!r.ok) throw new Error(`nau-filter: 마스크를 불러오지 못했습니다 ${u} (${r.status})`);
    return r.blob();
  }).then(b => createImageBitmap(b, { imageOrientation: "flipY", premultiplyAlpha: "none", colorSpaceConversion: "none" }))));
