  // 10/22: 목록에는 칸 번호만 담고(+ 고정, − 다시 놓기) 자리 · 난수는 셰이더(strokeIn)가 만든다 — 그림마다 CPU 약 27ms + 업로드 37MB가 없어졌다.
  // 그리는 순서(열쇠 ihash(칸, 층, 6) 순, 같으면 번호 순)는 층마다 한 번만 정렬해 두고(STROKE_ORDER), 칸 수가 바뀌면(획 크기 = 필터 세기) 앞 칸만 걸러 쓴다
  // — 걸러도 순서는 같다. 그래서 필터 세기를 움직여도 다시 정렬하지 않는다(크레용 한 칸에 0.5초 멈추던 것)
  const STROKE_ORDER = new Map();                            // 층 씨앗 → { cap, ord: 칸 번호를 그리는 순서로 }

  function strokeOrder(base, n) {
    let O = STROKE_ORDER.get(base);
    if (!O || O.cap < n) {                                    // 열쇠(float32 비트) × 2²¹ + 칸 번호를 숫자로 정렬 = (열쇠, 번호) 순
      const cap = Math.ceil(n * 1.5), keyF = new Float32Array(1), keyU = new Uint32Array(keyF.buffer), c = new Float64Array(cap);
      if (cap >= 2097152) throw new Error("획 칸이 너무 많다");
      for (let i = 0; i < cap; i++) { keyF[0] = ihash(i, base, 6); c[i] = keyU[0] * 2097152 + i; }
      c.sort();
      const ord = new Uint32Array(cap); for (let j = 0; j < cap; j++) ord[j] = c[j] % 2097152;
      STROKE_ORDER.set(base, O = { cap, ord });
    }
    return O.ord;
  }

  const strokeCache = new Map();

  function strokeList(li, spacing, W, H, boil = state.boil) {   // boil = 그림마다 새로 놓을 칸의 비율(크레용 잔획은 0 — 가늘고 대비가 커서 다시 놓이면 튄다)
    const gw = Math.ceil(W / spacing), gh = Math.ceil(H / spacing), n = gw * gh, base = 1000 + li * 97;
    const ck = `${li}|${spacing}|${W}|${H}|${boil}`;
    let S = strokeCache.get(ck);
    if (!S) {
