      for (let j = 0, o = 0; o < n; j++) { const i = ord[j]; if (i < n) data[o++] = ihash(i, base, 1) >= boil ? i + 1 : -(i + 1); }
      S = { data, n, gw, base, sx: spacing / W, sy: spacing / H, buf: null, tex: null };
