  function strokeUse(S, prog) {                               // 다시 놓는 획을 셰이더가 만들 값(칸 · 씨앗)
    gl.uniform1i(U(prog, "uSBase"), S.base); gl.uniform1i(U(prog, "uSSeed"), state.seed); gl.uniform1i(U(prog, "uSGw"), S.gw);
