  }

  function strokeAttrib(S) {                                  // 유화: 획 목록 버퍼를 strokeVAO의 획마다 속성으로
    if (!S.buf) { S.buf = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, S.buf); gl.bufferData(gl.ARRAY_BUFFER, S.data, gl.STATIC_DRAW); }
