  // 유화 · 획 세부 조정(기본값 = 지금까지의 고정값 — 그림이 바뀌지 않는다). w = 층별 붓 굵기 배율(굵은·중간·가는), len = 획 길이 배율,
  // jit = 획 색 흔들림(× 강도), bump·spec·canvas = 물감 요철·광택·캔버스 결 계수(× 강도), refineT = 보완 층 오차 문턱(null = 프리셋 값),
  // eye = 눈·코 테 정리(0 끔 = 예전 그림, 1 = 작은 검정 덩이 둘레의 회갈색 고리를 원본으로. 유화 v3만 프리셋에서 1, 11/02)
  // edge = 경계 밖 잔획 정리(0 끔 = 예전 그림, 1 = 원본이 평평한 곳에 남은 다른 색 조각을 원본으로. 11/05)
  // spill = 경계 옆 번짐 띠(0 끔 = 예전 그림, 1 = 붓이 평평한 다른 색 바탕으로 넘어가면 길이 · 폭을 거기서 멈춤. 11/05)
  // slope = 그늘 띠 붓 방향(0 끔 = 예전 그림, 1 = 결이 약한 곳의 기본 방향을 뚜렷한 그러데이션의 등고선 쪽으로. 11/05)
  // halo = 경계 둘레 테 정리(0 끔 = 예전 그림, 1 = 센 경계 가까이에서 칠의 흐린 평균을 원본의 흐린 평균에 맞춤. 11/05)
  // flowT = 붓 방향 시간 평활(0 끔 = 예전 그림, 0.6 = 앞 그림 방향을 60% 이어받음. 11/09)
  // layerH · ridge = 층별 높이 오프셋 · 획 옆 둑, cavity · varnish = 홈 그늘 · 바니시 광택(모두 0 끔 = 예전 그림. 11/09)
  const OIL = { w: [1, 1, 1], len: 1, jit: 0.05, bump: 6, spec: 0.1, canvas: 0.02, refineT: null, eye: 0, eyeDark: 0, edge: 0, spill: 0, slope: 0, halo: 0, flowT: 0, layerH: 0, ridge: 0, cavity: 0, varnish: 0 };

  function paintStrokes(P, t0) {
