    figUpdate(); FIG.use = FIG.tex;
    const eye = med === 1 ? OIL.eye : 0;
    const ed = OIL.eyeDark;                                    // 남색 눈도 덩이로(11/09, 0 = 예전 문턱 .14~.3 · 밝기 차 .4)
    if (eye > 0) pass(PR.blob, T.blob, { uTex: T.grade }, { uDkLo: .14 + .16*ed, uDkHi: .3 + .15*ed, uDkC: .4 + .05*ed });     // 작은 검정 덩이(눈·코) 지도: 노말 부위 경계에서 빼고, 합성에서 둘레 테를 걷는다
    if (FIG.mode === "mask" && CR.nk > 0 && FIG.imgs.length && med === 1) figCompute(T.grade, 3, eye);
    gl.bindFramebuffer(gl.FRAMEBUFFER, T.mrt); gl.viewport(0, 0, W, H);
    gl.useProgram(PR.under.p);
    gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, T.grade.t); gl.uniform1i(U(PR.under, "uGrade"), 0);
    gl.uniform1i(U(PR.under, "uMedium"), med);
    gl.bindVertexArray(vao); gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
    const pr = PR.stroke; gl.useProgram(pr.p);
    gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, T.grade.t); gl.uniform1i(U(pr, "uGrade"), 0);
    gl.activeTexture(gl.TEXTURE1); gl.bindTexture(gl.TEXTURE_2D, T.tfm.t); gl.uniform1i(U(pr, "uTFM"), 1);
    gl.activeTexture(gl.TEXTURE3); gl.bindTexture(gl.TEXTURE_2D, T.blob.t); gl.uniform1i(U(pr, "uBlob"), 3); gl.uniform1f(U(pr, "uEyeK"), eye);
    gl.uniform1f(U(pr, "uSpillK"), med === 1 ? OIL.spill : 0);
    gl.uniform2f(U(pr, "uRes"), W, H); gl.uniform1f(U(pr, "uSeedF"), state.seed % 97);
    gl.uniform1f(U(pr, "uHiCut"), 0.86); gl.uniform1f(U(pr, "uJit"), med === 1 ? OIL.jit * state.strength : 0.03);
    gl.activeTexture(gl.TEXTURE7); gl.bindTexture(gl.TEXTURE_2D, FIG.use); gl.uniform1i(U(pr, "uFig"), 7);
    gl.uniform1f(U(pr, "uNK"), med === 1 ? CR.nk : 0); gl.uniform3fv(U(pr, "uNL"), [CR.nlx, CR.nly, CR.nlz]);
    for (const [u, k] of [["uNDir", "ndir"], ["uNBand", "nband"], ["uNOTone", "notone"], ["uNWhite", "nwhite"], ["uNOBgDet", "nobgdet"], ["uNOEdge", "noedge"], ["uNOStep", "nostep"], ["uNOBand", "noband"], ["uNOPatch", "nopatch"], ["uNOSoft", "nosoft"], ["uNODark", "nodark"], ["uNOSil", "nosil"], ["uNOSilW", "nosilw"]]) gl.uniform1f(U(pr, u), CR[k]);
