    const flick = 1;                                          // 노출 깜빡임 없음 (10/15)
    pass(PR.compose, null, { uPaint: T.paint, uHgt: T.hgt, uGrade: T.grade, uSrc: srcTex, uFig: FIG.use, uBlob: T.blob },
      { uNK: med === 1 ? CR.nk : 0, uNL: [CR.nlx, CR.nly, CR.nlz], uNOMacro: CR.nomacro, uMedium: med, uStr: state.strength, uSplit: state.split, uFlick: flick, uSeedF: state.seed % 97, uBumpK: OIL.bump, uSpecK: OIL.spec, uCanvasK: OIL.canvas,
        uEyeK: eye, uEyeR: sz, uEdgeK: med === 1 ? OIL.edge : 0, uHaloK: med === 1 ? OIL.halo : 0, uCavK: med === 1 ? OIL.cavity : 0, uVarK: med === 1 ? OIL.varnish : 0 });
