  }

  // ---------- 드로잉 · 크레용 ----------
  // 평면화 정도는 '평면화' 슬라이더(state.flat). expo = 어두운 장면 밝기 끌어올리기(0 끔, 1 켬), white = 흰 털을 종이 흰색으로 정리하는 세기, sl = 영역 평균이 넘을 수 있는 밝기 차(클수록 큰 음영까지 걷는다), keep = 중간 크기 세부를 남기는 정도, shock = 경계의 섞인 색을 양쪽 색으로 붙이는 정도,
  // amb = 음영과 상관없는 결 획이 화면을 덮는 겹수, hatch = 걷어 낸 음영(밝기 차 1)이 덮는 겹수, gain = 빗금 색을 원래 음영보다 얼마나 더 벌릴지,
  // paper = 획 사이로 보이는 밑칠을 종이색 쪽으로, jit = 획마다 색 흔들림(톤을 늘리므로 기본 0), line = 윤곽 세기, ang = 평평한 곳의 손 방향(도)
  // edge = 경계 정리(넘어온 획 끝·한쪽으로 번진 짙은 테·계단을 원본 경계에 맞춤, 0~1), egrain = 경계 결(종이 결을 따라 잘게 부서지는 경계, 0~1), ew = 경계로 볼 폭(px, 이보다 가는 선은 그대로)
  const CR = { debug: 0, expo: 1, white: 1, sl: 0.2, keep: 1, shock: 1, amb: 0.6, hatch: 12, gain: 1.35, paper: 0, jit: 0, line: 0, ang: 65, e0: 2e-5, e1: 4e-4,
               edge: 0, egrain: 0, ew: 6, esmudge: 0, fine: 0, speck: 0,   // fine = 잔획 겹수(0~2), speck = 종이 알갱이(0~1)
               // 찢은 종이(크레용 콜라주): tear = 세기(0 끔), tearRag = 찢은 굴곡(px), tearFine = 잔 섬유, tearFiber = 흰 단면, tearShadow·tearLen·tearAng = 그림자 진하기·길이·방향(도)
               // 처음 값은 콜라주 v2의 CL 값(찢은 가장자리 1.88 · 잔 섬유 1.5 · 흰 단면 0.85 · 그림자 0.35 · 길이 2.2 · 300°)에 맞춘다
               tear: 0, tearRag: 1.88, tearFine: 1.5, tearFiber: 0.85, tearShadow: 0.35, tearLen: 2.2, tearAng: 300,
               nk: 0, ndir: 1, ntfm: .5, ntone: .6, nlit: .5, nfill: 0, nunder: 0, nbg: 1, ninner: 1, nwhite: .85, nband: .12, fk: 60, fk2: 30, fd0: 3, fcap: 30, fparts: 1, fblur: 10, fhs: 1, fstab: .05, fmthr: 30, fdead: .15, fedge: .12, fprof: 0, wlift: 0, tfmE: 4e-5, nlx: -.5, nly: .55, nlz: .65, nfine: 1, ntearbg: 1, notone: 0, nomacro: 0, nobgdet: 1, noedge: .1, nwdir: 0, nostep: 0, noband: .12, ninmode: 0, nopatch: 0, nosoft: .001, nodark: 0, nosil: 0, nosilw: 12,
               nbgp: 1, nchp: 1, nbglen: 1, nbgfine: 1, nchfine: 1, nchdet: 1 };   // 드로잉 흐름(노말 켬일 때, 1 = 그대로): 배경 · 캐릭터 누르는 힘, 배경 획 크기, 배경 · 캐릭터 잔획, 캐릭터 세부 문턱   // 캐릭터 노말(27번 실험)   // esmudge = 경계 번짐(오일파스텔처럼 경계를 가로질러 문질러 섞음, 0~1)

  // 밝은 쪽 95% 밝기(p95)가 낮은 장면만: g = 3(1−p95)/p95, 1~3 — p95를 약 0.75로. 가로 1 대기(어둑) p95 0.39 → g 3, 보통 장면 0.76~0.97 → 1(그대로)
  const CR_EXPO_LVL = 5, crPix = { buf: null };

  function crayonExposure() {
    const lv = CR_EXPO_LVL, w = Math.max(1, T.grade.w >> lv), h = Math.max(1, T.grade.h >> lv);
    if (!T.expoFb) T.expoFb = gl.createFramebuffer();
    gl.bindFramebuffer(gl.FRAMEBUFFER, T.expoFb);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, T.grade.t, lv);
    if (!crPix.buf || crPix.buf.length !== w * h * 4) crPix.buf = new Uint8Array(w * h * 4);
    gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, crPix.buf);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    const L = new Float32Array(w * h);
    for (let i = 0; i < w * h; i++) L[i] = (0.299 * crPix.buf[i * 4] + 0.587 * crPix.buf[i * 4 + 1] + 0.114 * crPix.buf[i * 4 + 2]) / 255;
    L.sort(); const p95 = Math.max(0.02, L[Math.floor(0.95 * (L.length - 1))]);
