    state.crG = g; state.crP95 = p95;
    if (g > 1.001) {                                          // T.paintC를 잠깐 빌려 T.grade를 다시 쓴다(밉도 다시 만든다)
      pass(PR.cexpo, T.paintC, { uTex: T.grade }, { uG: g });
      pass(PR.cexpo, T.grade, { uTex: T.paintC }, { uG: 1 });
    }
  }

  // ---------- 캐릭터 지도(노말, 27번 실험에서 옮김) ----------
  // 소스마다 캐릭터 마스크(R = 보이는 캐릭터 번호×40, G = 가리기 전 번호×40, 프레임마다 PNG 한 장)를 붙이면, 셰이더가 그림마다
  // 부풀린 노말을 만든다(점프 플러딩 거리 → 높이 → 같은 캐릭터 안 흐림 → 기울기 → 시간 안정화, 1080p GPU 약 2ms). 노말 쪽 값은 CR.n*.
  // 마스크가 없는 소스·구간은 '캐릭터 없음'(노말을 켜도 그림이 그대로)
  const FIG = { imgs: [], tex: null, cur: -2, use: null, mode: "mask", first: true, ms: 0, start: 0 };

  function figCompute(edgeTex = T.flat, lodE = 2, blobK = 0) {   // 마스크 → 노말(셰이더). 결과는 T.fS(시간 안정화한 캐릭터 지도). blobK > 0 = 작은 검정 덩이(T.blob)는 부위 경계에서 뺌
    const w = T.flat.w, h = T.flat.h;
    if (!T.fA || T.fA.w !== w || T.fA.h !== h) {
      for (const k of ["fA", "fB", "fH", "fH2", "fS", "fS2", "fL", "fLp"]) T[k] = tex(w, h, { float: true });
      T.fN = tex(w, h); FIG.first = true;
    }
    const t0 = performance.now();
    if (CR.fprof) gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, PIX);
    const t1 = performance.now();
