      for (const [u, unit] of [["uFlat", 0], ["uGrade", 1], ["uTFM", 2], ["uSST", 4], ["uWhite", 5], ["uFig", 7], ["uPA", 9], ["uPB", 10], ["uPC", 11]]) gl.uniform1i(U(p, u), unit);
