    T = { grade: tex(state.outW, state.outH, { mip: true }),
          sst: tex(fw, fh, { float: true }), sst2: tex(fw, fh, { float: true }), tfm: tex(fw, fh, { float: true }), tfmB: tex(fw, fh, { float: true }),
          akf: tex(qw, qh, { mip: true }) };
    T.paint = { ...tex(aw, ah, { mip: true }), w: state.outW, h: state.outH }; T.hgt = { ...tex(aw, ah, { mip: true }), w: state.outW, h: state.outH };
    T.paintC = tex(state.outW, state.outH);
    T.akfB = tex(qw, qh, { mip: true });
    T.flat = tex(qw, qh, { mip: true });
    T.sstB = tex(fw, fh, { float: true }); T.sstB2 = tex(fw, fh, { float: true });
    T.white = tex(qw, qh);
    T.blob = tex(Math.round(state.outW / 4), Math.round(state.outH / 4));   // 유화: 작은 검정 덩이(눈·코) 지도(OIL.eye, 가상 크기 ¼)
    const rw = Math.max(1, Math.round(qw / 8)), rh = Math.max(1, Math.round(qh / 8));
    T.regA = tex(rw, rh); T.regB = tex(rw, rh);
    T.mrt = gl.createFramebuffer(); gl.bindFramebuffer(gl.FRAMEBUFFER, T.mrt);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, T.paint.t, 0);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT1, gl.TEXTURE_2D, T.hgt.t, 0);
    gl.drawBuffers([gl.COLOR_ATTACHMENT0, gl.COLOR_ATTACHMENT1]);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    VR.big = new Set([null, T.mrt, T.paint.fb]); setVK(VR.kx);
    state.dirty = true;
  }
  function upload(src) {                                    // 원본 → srcTex(위아래를 뒤집어 올린다. { data }와 ImageBitmap은 이미 뒤집힌 것으로 본다)
    gl.bindTexture(gl.TEXTURE_2D, srcTex);
    if (src.data) gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, src.width, src.height, 0, gl.RGBA, gl.UNSIGNED_BYTE, src.data);
    else {
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, src);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
    }
  }
  // 알파로 마스크(10/22, 푸빌라 미믹처럼 캐릭터를 투명 캔버스에 따로 그리는 앱): 알파 > .5 = 번호 id(R = G = id×40). GPU에서 반 해상도로 바꿔
  // FIG.tex에 복사한다 — 화소를 CPU로 읽어 오지 않는다
  const AM = { prog: null, src: null, rt: null };
  function alphaToMask(src, id) {
    const [w, h] = sizeOf(src), mw = Math.max(1, Math.round(w / 2)), mh = Math.max(1, Math.round(h / 2));
    if (!AM.prog) AM.prog = compile(`#version 300 es
precision highp float; in vec2 vUV; out vec4 o; uniform sampler2D uA; uniform float uV;
void main(){ float v = texture(uA, vUV).a > .5 ? uV : 0.; o = vec4(v, v, 0., 1.); }`);
    if (!AM.src) {
      AM.src = gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D, AM.src);
      for (const [k, v] of [[gl.TEXTURE_MIN_FILTER, gl.LINEAR], [gl.TEXTURE_MAG_FILTER, gl.LINEAR], [gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, k, v);
    }
    if (!AM.rt || AM.rt.w !== mw || AM.rt.h !== mh) { if (AM.rt) { gl.deleteTexture(AM.rt.t); gl.deleteFramebuffer(AM.rt.fb); } AM.rt = tex(mw, mh); }
    gl.bindTexture(gl.TEXTURE_2D, AM.src);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, !isBitmap(src));
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, src);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
    pass(AM.prog, AM.rt, { uA: AM.src }, { uV: id * 40 / 255 });
    gl.bindFramebuffer(gl.FRAMEBUFFER, AM.rt.fb); gl.bindTexture(gl.TEXTURE_2D, FIG.tex);
    gl.copyTexImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 0, 0, mw, mh, 0);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  }
  function figUpdate() {                                    // 이번 그림의 마스크를 그림마다 한 번 올린다
    if (!FIG.imgs.length || FIG.cur === state.draw) return;
    const m = FIG.imgs[0];
    if (m.alphaOf) { alphaToMask(m.alphaOf, m.id); FIG.cur = state.draw; return; }
    gl.bindTexture(gl.TEXTURE_2D, FIG.tex);
    if (m.data) gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, m.width, m.height, 0, gl.RGBA, gl.UNSIGNED_BYTE, m.data);
    else {
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, !isBitmap(m));
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, m);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
    }
    FIG.cur = state.draw;
  }
  // 갤러리 renderBase에서 이 세 필터의 갈래만(유화 = 획 기반 sbr, 크레용 = crayon)
  const TFMH = { on: false };                                // 붓 방향 시간 평활의 앞 그림이 있는가(판을 새로 잡거나 reset하면 지운다)
  function renderBase() {
    const P = PRESETS[state.preset];
    const t0 = performance.now();
    upload(cur);
    if (CR.wlift > 0 && CR.nk > 0) figUpdate();
    pass(PR.grade, T.grade, { uSrc: srcTex, uFigM: FIG.tex || srcTex }, { uAmt: state.grade, uKeepW: GRADE.keepW, uWLift: CR.nk > 0 ? CR.wlift : 0 });
    if (P.crayon) crayonExposure();
    pass(PR.sst, T.sst, { uTex: T.grade });
    pass(PR.blur, T.sst2, { uTex: T.sst }, { uDir: [1 / T.sst.w, 0], uSigma: 2.5 });
    pass(PR.blur, T.sst, { uTex: T.sst2 }, { uDir: [0, 1 / T.sst.h], uSigma: 2.5 });
    const flowK = P.sbr === 1 && TFMH.on ? OIL.flowT : 0;      // 붓 방향 시간 평활: 앞 그림 TFM을 읽어 다른 판에 쓰고 바꿔 든다
    if (flowK > 0) { pass(PR.tfm, T.tfmB, { uTex: T.sst, uGr: T.grade, uPrev: T.tfm }, { uStrE: CR.tfmE, uSlopeK: P.sbr === 1 ? OIL.slope : 0, uFlowK: flowK }); [T.tfm, T.tfmB] = [T.tfmB, T.tfm]; }
    else pass(PR.tfm, T.tfm, { uTex: T.sst, uGr: T.grade }, { uStrE: CR.tfmE, uSlopeK: P.sbr === 1 ? OIL.slope : 0, uFlowK: 0 });
    TFMH.on = P.sbr === 1 && OIL.flowT > 0;
    if (P.sbr) { paintStrokes(P, t0); return; }
    if (P.akf) {
      pass(PR.akf, T.akf, { uTex: T.grade, uTFM: T.tfm },
        { uSrcTexel: [1 / T.grade.w, 1 / T.grade.h], uRadius: Math.max(2, P.akf * state.size * AKF.k), uLod: Math.log2(1 / state.q), uQ: state.q, uHard: 8, uSharp: 8 });
      if (P.akf2) {
        pass(PR.akf, T.akfB, { uTex: T.akf, uTFM: T.tfm },
          { uSrcTexel: [1 / T.akf.w, 1 / T.akf.h], uRadius: Math.max(2, P.akf * state.size * 0.7 * AKF.k), uLod: 0, uQ: 1, uHard: 8, uSharp: 8 });
        const tmp = T.akf; T.akf = T.akfB; T.akfB = tmp;
      }
    }
    if (P.crayon) { paintCrayon(P, t0); return; }
  }
  // 갤러리 applyTune과 같은 순서: 코드 기본 → 프리셋 tune → 필터 세기(+노말 · 그림체) → 바꾼 세부 값
  function applyTune() {
    for (const [name, snap] of Object.entries(TUNE_SNAP))
      for (const [k, v] of Object.entries(snap)) {
        const o = TUNE_OBJ[name], c = v && typeof v === "object" ? JSON.parse(JSON.stringify(v)) : v;
        if (Array.isArray(v)) o[k].splice(0, o[k].length, ...c); else o[k] = c;
      }
    for (const [path, v] of Object.entries(PRESETS[state.preset]?.tune || {})) tuneSet(path, v);
    levelApply(state.preset);
    for (const [path, v] of Object.entries(memo[state.preset]?.tune || {})) tuneSet(path, v);
    if (light) [CR.nlx, CR.nly, CR.nlz] = light;
    state.dirty = true;
  }
  function loadValues() {                                   // 갤러리 valuesOf: 프리셋 처음 값 + 바꾼 값
    const v = { ...defaultsOf(state.preset), ...(memo[state.preset]?.values || {}) };
    for (const k of ["strength", "size", ...VALUE_KEYS]) state[k] = v[k];
  }
  function validTune(t) {
    const out = {};
    for (const [path, v] of Object.entries(t || {})) {
      let ok = false;
      try { const [o, k] = tunePath(path); ok = !!o && k in o && typeof v === "number" && isFinite(v); } catch (e) {}
      if (ok) out[path] = v; else console.warn(`nau-filter: 세부 값 '${path}'를 건너뜁니다(이 모듈에 없는 경로이거나 숫자가 아님)`);
    }
    return out;
  }

  // 갤러리 '설정 저장' 파일(전체) 또는 공유 링크 형식(필터 하나)을 받는다. 필터 세기 · 노말은 파일이 가리키는 필터의 값으로
  function loadSettings(d) {
    if (typeof d === "string") d = JSON.parse(d);
    if (!d || d.app !== SETTINGS_TAG) throw new Error("nau-filter: 필터 갤러리 설정 파일이 아닙니다");
    const put = (k, values, tune) => {
      if (!LEVELS[k]) return;
      const vals = Object.fromEntries(VALUE_KEYS.filter(x => typeof values?.[x] === "number").map(x => [x, values[x]]));
      memo[k] = { values: vals, tune: validTune(tune) };
    };
    let top = null;
    if (d.memo || d.tune) { for (const k of new Set([...Object.keys(d.memo || {}), ...Object.keys(d.tune || {})])) put(k, d.memo?.[k], d.tune?.[k]); top = d.memo?.[d.preset]; }
    else { put(d.preset, d.values, d.tune); top = d.values; }
    const o = {};
    if (LEVELS[d.preset]) o.filter = d.preset;
    if (typeof top?.level === "number") o.level = top.level;
    if (typeof top?.normal === "number") o.normal = !!top.normal;
    set(o);
  }

  function set(o = {}) {
    if (o.settings) loadSettings(o.settings);
    if (o.filter !== undefined) state.preset = filterKey(o.filter);
    const m = memo[state.preset] || (memo[state.preset] = { values: {}, tune: {} });
    for (const k of VALUE_KEYS) if (o[k] !== undefined) m.values[k] = +o[k];
    if (o.tune === null) m.tune = {};                        // 바꾼 세부 값을 지우고 필터 세기 값으로 되돌린다(이 필터만)
    else if (o.tune) Object.assign(m.tune, validTune(o.tune));
    if (o.level !== undefined) state.level = Math.max(0, Math.min(100, +o.level));
    if (o.normal !== undefined) state.normal = o.normal ? 1 : 0;
    if (o.style !== undefined) { if (o.style !== "flat" && o.style !== "3d") throw new Error("nau-filter: style은 'flat' 또는 '3d'"); state.style = o.style; }
    if (o.light !== undefined) light = o.light ? [+o.light[0], +o.light[1], +o.light[2]] : null;
    if (o.profile !== undefined) state.profile = !!o.profile;
    let re = false;                                          // 실제 · 가상 크기가 바뀌면 판을 다시 잡는다(한 번만)
    if (o.short !== undefined && +o.short > 0 && +o.short !== state.short) { state.short = +o.short; re = true; }
    if (o.px !== undefined && +o.px > 0 && +o.px !== state.px) { state.px = +o.px; re = true; }
    if (re && state.srcW) allocate(state.srcW, state.srcH);
    loadValues(); applyTune();
    return api;
  }

  // 시각 t(초)에 render하면 새 그림을 그리는가. 장면을 그 때만 그리면(마스크 패스 포함) 웹 인터랙티브의 GPU를 아낀다
  function due(t = performance.now() / 1000) { return state.dirty || !T || Math.floor(t * state.fps + 1e-6) !== state.tick; }
  // 그림 한 장: 초당 그림 수(fps)마다 한 번 새로 그리고, 그 사이에는 캔버스가 앞 그림을 그대로 둔다. 새로 그렸으면 true
  function render(source, o = {}) {
    if (!source || !readyOf(source)) return false;
    const [w, h] = sizeOf(source);
    if (!w || !h) return false;
    if (!T || w !== state.srcW || h !== state.srcH) allocate(w, h);
    const t = o.time ?? (source.currentTime ?? performance.now() / 1000);
    const tick = Math.floor(t * state.fps + 1e-6);
    if (tick === state.tick && !state.dirty && !o.force) return false;
    state.tick = tick; state.seed = tick % 997; state.dirty = false; state.draw++;
    const mask = o.maskAlpha ? { alphaOf: o.maskAlpha, id: o.maskId ?? 1 } : typeof o.mask === "function" ? o.mask(t) : o.mask;   // maskAlpha = 캐릭터만 그린 투명 캔버스
    if (mask) { if (!FIG.imgs.length) FIG.first = true; FIG.imgs = [mask]; }
    else if (FIG.imgs.length) { FIG.imgs = []; figBlank(); }           // 마스크 없음 = 캐릭터 없음(노말을 켜도 그림이 그대로)
    cur = source;
    renderBase();
    return true;
  }

  function reset() { FIG.first = true; state.tick = -1; state.dirty = true; TFMH.on = false; }   // 장면이 바뀌었을 때: 노말 시간 안정화를 처음부터
  let disposed = false;
  function dispose() {
    if (disposed) return; disposed = true;
    freeTargets();
    if (srcTex) gl.deleteTexture(srcTex);
    gl.deleteTexture(FIG.tex);
    if (AM.prog) gl.deleteProgram(AM.prog.p); if (AM.src) gl.deleteTexture(AM.src); if (AM.rt) { gl.deleteTexture(AM.rt.t); gl.deleteFramebuffer(AM.rt.fb); }
    for (const p of Object.values(PR)) gl.deleteProgram(p.p);
    gl.deleteBuffer(strokeBuf); gl.deleteVertexArray(strokeVAO); gl.deleteVertexArray(vao);
    for (const S of strokeCache.values()) { if (S.buf) gl.deleteBuffer(S.buf); if (S.tex) gl.deleteTexture(S.tex); }
    strokeCache.clear();
    for (const t of CPREP.out) gl.deleteTexture(t);
    if (CPREP.fb) gl.deleteFramebuffer(CPREP.fb);
    gl.getExtension("WEBGL_lose_context")?.loseContext();
  }

  const api = {
    canvas: out, gl, render, due, set, reset, dispose, loadSettings,
    get options() {
      return { filter: state.preset, level: state.level, normal: !!state.normal, style: state.style, light: light && [...light],
               fps: state.fps, boil: state.boil, grade: state.grade, flat: state.flat, short: state.short, px: state.px, tune: { ...(memo[state.preset]?.tune || {}) } };
    },
    get info() {
      return { filter: state.preset, label: PRESETS[state.preset].label, width: out.width, height: out.height, virtual: [state.outW, state.outH],
               ms: state.lastMs, fps: state.fps, tick: state.tick, mask: FIG.imgs.length > 0, normal: CR.nk > 0 };
    },
    _debug: { state, CR, OIL, FIG, get T() { return T; } },
  };
  set({ filter: "crayon", ...options });
  return api;
}
